states.154a45a43099:
[
 {
  "zaman": "21.02.2023 10:14",
  "konusan": "temsilci",
  "metin": "Alo DASK 125, ben Gökhan, size nasıl yardımcı olabilirim?"
 },
 {
  "zaman": "21.02.2023 10:14",
  "konusan": "arayan",
  "metin": "Merhaba, Malatya'dan arıyorum, adım Şehriban Doğrusöz. İki dairem var, ikisi de hasarlı. Birinin ihbarını 9 Şubat'ta e-Devlet'ten yaptım, avans çıkıyor mu onu öğrenmek istiyorum. Öbürü için de ne yapacağımı bilmiyorum açıkçası."
 },
 {
  "zaman": "21.02.2023 10:16",
  "konusan": "temsilci",
  "metin": "Çok geçmiş olsun. Kimlik numaranızla baktım: Battalgazi, Kayısılı Sokak'taki daireniz için 14.09.2022 başlangıçlı, 14.09.2023 bitişli poliçeniz var; 09.02.2023 tarihli ihbarınız da görünüyor. Bakanlığın hasar tespitinde bina 'ağır hasarlı'. Poliçedeki sigorta bedeli 512.000 TL."
 },
 {
  "zaman": "21.02.2023 10:17",
  "konusan": "arayan",
  "metin": "Evet, orası oturduğum ev. Yalnız tapuda yarı yarıya, yarısı ağabeyim Nurettin'in üstüne."
 },
 {
  "zaman": "21.02.2023 10:18",
  "konusan": "temsilci",
  "metin": "Yıkık, acil yıkılacak ve ağır hasarlı binalarda sigorta bedelinin yüzde 20'si, orta hasarlılarda yüzde 10'u avans olarak ödeniyor. Ödeme tapudaki hisseler oranında, her malikin kendi IBAN'ına yapılıyor. Sizin IBAN'ınız kayıtlı, payınız sıradaki ödeme listesine girebilir. Ağabeyinizin payı için onun da kimlik ve IBAN bilgisini iletmesi gerekiyor."
 },
 {
  "zaman": "21.02.2023 10:19",
  "konusan": "arayan",
  "metin": "Tamam. Peki Yeşilyurt'taki daire? Orada kiracım var, bina 'orta hasarlı' çıktı. Onun poliçesi 30 Ocak'ta bitmiş meğer. Bankadan SMS gelmişti, ben otomatik yenilenir sandım. Depremden sonra, 10 Şubat'ta yeniden yaptırdım."
 },
 {
  "zaman": "21.02.2023 10:21",
  "konusan": "temsilci",
  "metin": "Kayıtta da öyle görünüyor: önceki poliçe 30.01.2023'te sona ermiş, yeni poliçe 10.02.2023 başlangıçlı ve primi aynı gün ödenmiş. 6 Şubat'ta o daire için yürürlükte bir poliçe olmadığından 6 Şubat depremlerindeki hasar maalesef karşılanamıyor. Yeni poliçe, başlangıç tarihinden sonraki depremler için geçerli."
 },
 {
  "zaman": "21.02.2023 10:22",
  "konusan": "arayan",
  "metin": "Dün akşamki depremde Yeşilyurt'taki evin salon duvarındaki çatlak iyice açılmış, kiracım fotoğraf attı. Onu da mı karşılamıyorsunuz?"
 },
 {
  "zaman": "21.02.2023 10:23",
  "konusan": "temsilci",
  "metin": "20 Şubat depremi yeni poliçenizin süresi içinde. O depremin yol açtığı ek hasar için ayrı bir ihbar açabiliriz; eksper, 6 Şubat'tan kalan hasarı ayırıp yalnızca 20 Şubat'ta oluşan hasarı değerlendirir. Açmamı ister misiniz?"
 },
 {
  "zaman": "21.02.2023 10:23",
  "konusan": "arayan",
  "metin": "Açın lütfen. Bir de kiracımın eşyaları da zarar gördü; ben de şu an Elazığ'da kız kardeşimin yanındayım, bir ev tutsam kirasını verir misiniz?"
 },
 {
  "zaman": "21.02.2023 10:25",
  "konusan": "temsilci",
  "metin": "Zorunlu deprem sigortası yalnızca binayı teminat altına alıyor; eşya, kira kaybı ya da geçici konaklama masrafları teminat dışında, bunları karşılayamıyoruz. Yeşilyurt için 20 Şubat depremine ilişkin ihbarınızı açtım, dosya numarası cep telefonunuza SMS ile gelecek."
 },
 {
  "zaman": "21.02.2023 10:26",
  "konusan": "arayan",
  "metin": "Anladım, sağ olun. Yorgunuz ama hayattayız, ona şükür. Ağabeyime söyleyeyim, o da IBAN'ını göndersin."
 }
]
